function quietBadge(badges) {
    for (let i = 0; i < badges.length; i++) {
        let count = 0;
        for (const badge of badges)
            if (badge === badges[i])
                count++;
        if (count === 1)
            return i;
    }
    return -1;
}

function quietBadge(badges) {
    const counts = new Map();
    for (const badge of badges)
        counts.set(badge, (counts.get(badge) ?? 0) + 1);
    for (let i = 0; i < badges.length; i++)
        if (counts.get(badges[i]) === 1)
            return i;
    return -1;
}
